// Bubble-wrapped AND gate. The in2 input goes to an AND gate, but there is a
// bubble between the input and the AND gate, so the bubble gives the path the
// shortest path: in2 -> AND -> out.
module TopModule(
    input  in1,
    input  in2,
    output out
);
    wire and_out;
    and #(1) AND (and_out, in1, in2);
    buf #(1) BUF (out, and_out);
endmodule

