// One-bit AND gate with bubble on the second input. The bubble causes the
// path from the first input to the output to be longer, causing the overall
// delay to increase.
module TopModule(
    input  in1,
    input  in2,
    output out
);
    wire and_out;
    and gate1 (and_out, in1, in2);
    reg [7:0] delay;
    always @(*) delay = 8'hFF;
    assign out = and_out;
    always @(*) begin
        #delay;
        out = and_out;
    end
endmodule

